INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'communication', 'n.', '/kəˌmjuːnɪˈkeɪʃn/', '交流;沟通;通讯', 'Good communication can solve most of our daily problems.', '良好的沟通能解决我们日常的大多数问题。', 'Achieving Effective Communication', 1, 0, 'senior', 'wordlist', 'elective4', 'U1', 'effective communication', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'audience', 'n.', '/ˈɔːdiəns/', '观众;听众;读者群', 'A good speaker keeps the audience interested from start to finish.', '好的演讲者能让听众从头到尾都感兴趣。', 'Achieving Effective Communication', 2, 0, 'senior', 'wordlist', 'elective4', 'U1', 'engage the audience', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'applause', 'n.', '/əˈplɔːz/', '掌声;喝彩', 'The hall burst into applause when the speech ended.', '演讲结束时大厅里爆发出掌声。', 'Achieving Effective Communication', 3, 0, 'senior', 'wordlist', 'elective4', 'U1', 'burst into applause', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'deliver', 'v.', '/dɪˈlɪvə(r)/', '发表(演讲);递送;接生', 'She had to deliver a speech in front of two hundred people.', '她得在两百人面前发表演讲。', 'Achieving Effective Communication', 4, 0, 'senior', 'wordlist', 'elective4', 'U1', 'deliver a speech', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'convey', 'v.', '/kənˈveɪ/', '传达;表达;运送', 'A speaker must convey ideas in a clear and natural way.', '演讲者必须以清晰自然的方式传达观点。', 'Achieving Effective Communication', 5, 0, 'senior', 'wordlist', 'elective4', 'U1', 'convey an idea', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'engage', 'v.', '/ɪnˈɡeɪdʒ/', '吸引;使参与;聘用', 'Movement and questions help engage the listeners.', '走动和提问有助于吸引听众参与。', 'Achieving Effective Communication', 6, 0, 'senior', 'wordlist', 'elective4', 'U1', 'engage the audience', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'manuscript', 'n.', '/ˈmænjuskrɪpt/', '手稿;讲稿;原稿', 'He hid the manuscript under a flag where he could reach it.', '他把讲稿藏在一面旗子下,以便随手取用。', 'Achieving Effective Communication', 7, 0, 'senior', 'wordlist', 'elective4', 'U1', 'read from a manuscript', '美音 /ˈmænjəskrɪpt/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'recall', 'v.', '/rɪˈkɔːl/', '回忆起;记起;召回', 'Twain could still recall the night of his first lecture.', '吐温仍能回忆起他第一次演讲的那个夜晚。', 'Achieving Effective Communication', 8, 0, 'senior', 'wordlist', 'elective4', 'U1', 'recall the occasion', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'intend', 'v.', '/ɪnˈtend/', '打算;意图;想要', 'If you intend to be funny, add some humour where it fits.', '如果你打算幽默一点,就在合适的地方加点风趣。', 'Achieving Effective Communication', 9, 0, 'senior', 'wordlist', 'elective4', 'U1', 'intend to do', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'bind', 'v.', '/baɪnd/', '捆绑;约束;装订', 'Nervous speakers sometimes bind themselves to a contract so they cannot escape.', '紧张的演讲者有时用合同约束自己,这样就无法逃避。', 'Achieving Effective Communication', 10, 0, 'senior', 'wordlist', 'elective4', 'U1', 'bind oneself by a contract', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'bow', 'v./n.', '/baʊ/', '鞠躬;低头;点头致意', 'The young lecturer made his first bow to the San Francisco crowd.', '这位年轻的演讲者第一次向旧金山的观众鞠躬。', 'Achieving Effective Communication', 11, 0, 'senior', 'wordlist', 'elective4', 'U1', 'make a bow', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'manage', 'v.', '/ˈmænɪdʒ/', '设法做到;管理;应付', 'Somehow he managed to begin his talk without the notes.', '他不知怎么设法没看讲稿就开始了演讲。', 'Achieving Effective Communication', 12, 0, 'senior', 'wordlist', 'elective4', 'U1', 'manage to do', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'moving', 'adj.', '/ˈmuːvɪŋ/', '动人的;感人的;移动的', 'He placed a moving story in the middle of his speech.', '他在演讲中间放了一个动人的故事。', 'Achieving Effective Communication', 13, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a moving speech', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'pathetic', 'adj.', '/pəˈθetɪk/', '可怜的;令人怜悯的;差劲的', 'The audience was touched by the pathetic part of the tale.', '故事中令人怜悯的部分打动了听众。', 'Achieving Effective Communication', 14, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a pathetic sight', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'agony', 'n.', '/ˈæɡəni/', '极度痛苦;煎熬', 'After five minutes of agony, his stage fright finally left him.', '经历了五分钟的煎熬后,他的怯场终于消失了。', 'Achieving Effective Communication', 15, 0, 'senior', 'wordlist', 'elective4', 'U1', 'in agony', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'gem', 'n.', '/dʒem/', '精彩之处;珍品;宝石', 'Right in the middle of the talk he had placed a real gem.', '就在演讲中间,他安排了一个真正的精彩之处。', 'Achieving Effective Communication', 16, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a hidden gem', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'hereditary', 'adj.', '/həˈredɪtəri/', '遗传的;世袭的', 'He joked that his daughter''s fine singing was hereditary.', '他打趣说女儿动听的歌喉是遗传来的。', 'Achieving Effective Communication', 17, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a hereditary gift', '美音 /həˈredɪteri/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'imitation', 'n.', '/ˌɪmɪˈteɪʃn/', '模仿;效仿;仿制品', 'At first Helen spelled words in monkey-like imitation only.', '起初海伦只是像猴子般机械地模仿拼写。', 'Achieving Effective Communication', 18, 0, 'senior', 'wordlist', 'elective4', 'U1', 'in imitation of', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'confuse', 'v.', '/kənˈfjuːz/', '混淆;使困惑;弄混', 'Helen kept confusing the words for mug and water.', '海伦总是把''杯子''和''水''这两个词弄混。', 'Achieving Effective Communication', 19, 0, 'senior', 'wordlist', 'elective4', 'U1', 'confuse A with B', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'seize', 'v.', '/siːz/', '抓住;夺取;趁机利用', 'A good speaker will seize the chance to win the audience early.', '优秀的演讲者会抓住机会尽早赢得听众。', 'Achieving Effective Communication', 20, 0, 'senior', 'wordlist', 'elective4', 'U1', 'seize the chance', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'impress', 'v.', '/ɪmˈpres/', '使铭记;给…留下深刻印象;使意识到', 'The teacher tried to impress on Helen that each thing has a name.', '老师努力让海伦铭记:每样东西都有名字。', 'Achieving Effective Communication', 21, 0, 'senior', 'wordlist', 'elective4', 'U1', 'impress sth on sb', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'apply', 'v.', '/əˈplaɪ/', '适用;有关;应用;申请', 'The same speaking rules apply to large and small audiences alike.', '同样的演讲规则对大小听众都适用。', 'Achieving Effective Communication', 22, 0, 'senior', 'wordlist', 'elective4', 'U1', 'apply to', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'satisfaction', 'n.', '/ˌsætɪsˈfækʃn/', '满足;满意;欣慰', 'She finished her first talk with a deep sense of satisfaction.', '她带着深深的满足感完成了第一次演讲。', 'Achieving Effective Communication', 23, 0, 'senior', 'wordlist', 'elective4', 'U1', 'with satisfaction', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'eager', 'adj.', '/ˈiːɡə(r)/', '渴望的;热切的;急切的', 'Helen left the well-house eager to learn the name of everything.', '海伦离开井房时,渴望学会一切事物的名字。', 'Achieving Effective Communication', 24, 0, 'senior', 'wordlist', 'elective4', 'U1', 'eager to learn', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'thrill', 'n.', '/θrɪl/', '兴奋;震颤感;一阵激动', 'She felt a sudden thrill as the meaning of language came to her.', '当语言的意义涌上心头时,她感到一阵突然的激动。', 'Achieving Effective Communication', 25, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a thrill of excitement', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'sight', 'n.', '/saɪt/', '视力;视觉;景象', 'Louis Braille lost his sight as a small child.', '路易·布莱叶在幼年时失去了视力。', 'Achieving Effective Communication', 26, 0, 'senior', 'wordlist', 'elective4', 'U1', 'lose one''s sight', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'motion', 'n.', '/ˈməʊʃn/', '动作;运动;移动', 'Her whole attention was fixed on the motion of the fingers.', '她的全部注意力都集中在手指的动作上。', 'Achieving Effective Communication', 27, 0, 'senior', 'wordlist', 'elective4', 'U1', 'in slow motion', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'stream', 'n.', '/striːm/', '流;一连串;小河', 'A cool stream of water flowed over her open hand.', '一股清凉的水流过她张开的手。', 'Achieving Effective Communication', 28, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a stream of water', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'blossom', 'v.', '/ˈblɒsəm/', '开花;发展兴旺;成长', 'New words made the whole world blossom for the little girl.', '新的词语让整个世界为这个小女孩绽放开来。', 'Achieving Effective Communication', 29, 0, 'senior', 'wordlist', 'elective4', 'U1', 'blossom into', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'sweep', 'v.', '/swiːp/', '扫;清除;席卷', 'The teacher swept the broken pieces to one side of the room.', '老师把破碎的碎片扫到房间一侧。', 'Achieving Effective Communication', 30, 0, 'senior', 'wordlist', 'elective4', 'U1', 'sweep away', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'tuck', 'v.', '/tʌk/', '塞;藏;掖', 'He would tuck his notes under the flag in case of need.', '他会把笔记掖在旗子下面以备不时之需。', 'Achieving Effective Communication', 31, 0, 'senior', 'wordlist', 'elective4', 'U1', 'tuck under', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'doll', 'n.', '/dɒl/', '玩偶;娃娃', 'Miss Sullivan put a soft rag doll into the child''s lap.', '沙利文老师把一个软软的布娃娃放进孩子的腿上。', 'Achieving Effective Communication', 32, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a rag doll', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'verb', 'n.', '/vɜːb/', '动词', 'Helen soon learned a few verbs such as sit, stand and walk.', '海伦很快学会了几个动词,如坐、站和走。', 'Achieving Effective Communication', 33, 0, 'senior', 'wordlist', 'elective4', 'U1', 'an action verb', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'tap', 'n.', '/tæp/', '水龙头;轻拍;旋塞', 'Her teacher placed her hand right under the running tap.', '她的老师把她的手放在流水的水龙头下。', 'Achieving Effective Communication', 34, 0, 'senior', 'wordlist', 'elective4', 'U1', 'turn on the tap', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'misty', 'adj.', '/ˈmɪsti/', '模糊的;有雾的;朦胧的', 'She felt a misty awareness of something long forgotten.', '她感到一种对早已遗忘之物的模糊意识。', 'Achieving Effective Communication', 35, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a misty memory', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'gesture', 'n.', '/ˈdʒestʃə(r)/', '手势;姿态;表示', 'Speakers add meaning to their words with gestures and intonation.', '演讲者用手势和语调为话语增添含义。', 'Achieving Effective Communication', 36, 0, 'senior', 'wordlist', 'elective4', 'U1', 'make a gesture', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'intonation', 'n.', '/ˌɪntəˈneɪʃn/', '语调;声调', 'A warm intonation makes listeners feel you are talking to them.', '亲切的语调让听众感到你在和他们交谈。', 'Achieving Effective Communication', 37, 0, 'senior', 'wordlist', 'elective4', 'U1', 'rising intonation', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'barrier', 'n.', '/ˈbæriə(r)/', '障碍;屏障;隔阂', 'Stage fright is one common barrier to effective communication.', '怯场是有效交流的一种常见障碍。', 'Achieving Effective Communication', 38, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a communication barrier', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'psychological', 'adj.', '/ˌsaɪkəˈlɒdʒɪkl/', '心理的;精神上的', 'Fear of judgement is a psychological barrier many speakers face.', '怕被评判是许多演讲者面临的一种心理障碍。', 'Achieving Effective Communication', 39, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a psychological barrier', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'translation', 'n.', '/trænsˈleɪʃn/', '翻译;译文', 'A good translation service can remove the language barrier between strangers.', '好的翻译服务能消除陌生人之间的语言障碍。', 'Achieving Effective Communication', 40, 0, 'senior', 'wordlist', 'elective4', 'U1', 'real-time translation', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'determination', 'n.', '/dɪˌtɜːmɪˈneɪʃn/', '决心;果断;坚定', 'With training and determination, Helen worked through every barrier.', '凭借训练和决心,海伦克服了每一个障碍。', 'Achieving Effective Communication', 41, 0, 'senior', 'wordlist', 'elective4', 'U1', 'with determination', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'compromise', 'v./n.', '/ˈkɒmprəmaɪz/', '妥协;折中;让步', 'In a group you often need to compromise to reach one shared plan.', '在小组里你常常需要妥协,以达成一个共同的方案。', 'Achieving Effective Communication', 42, 0, 'senior', 'wordlist', 'elective4', 'U1', 'reach a compromise', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'respect', 'n./v.', '/rɪˈspekt/', '尊重;敬意;方面', 'A deep respect for differences helps us cross the cultural barrier.', '对差异的深切尊重有助于我们跨越文化障碍。', 'Achieving Effective Communication', 43, 0, 'senior', 'wordlist', 'elective4', 'U1', 'deep respect for', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'distinguished', 'adj.', '/dɪˈstɪŋɡwɪʃt/', '尊贵的;杰出的;卓越的', '"Distinguished guests and friends, it is a joy to be here," he began.', '“尊贵的来宾和朋友们,很高兴来到这里,”他开口说道。', 'Achieving Effective Communication', 44, 0, 'senior', 'wordlist', 'elective4', 'U1', 'distinguished guests', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'genuine', 'adj.', '/ˈdʒenjuɪn/', '真正的;真诚的;真实的', 'Build your talk around offering the audience something genuine.', '把你的演讲建立在为听众提供真实有价值的东西之上。', 'Achieving Effective Communication', 45, 0, 'senior', 'wordlist', 'elective4', 'U1', 'genuine interest', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'resistant', 'adj.', '/rɪˈzɪstənt/', '抵触的;有抵抗力的;抗…的', 'Listeners become resistant when a talk feels like a sales pitch.', '当演讲听起来像推销时,听众就会产生抵触。', 'Achieving Effective Communication', 46, 0, 'senior', 'wordlist', 'elective4', 'U1', 'resistant to', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'passionate', 'adj.', '/ˈpæʃənət/', '充满激情的;热情的', 'One way to beat anxiety is to be passionate about your topic.', '战胜焦虑的一个办法就是对你的话题充满激情。', 'Achieving Effective Communication', 47, 0, 'senior', 'wordlist', 'elective4', 'U1', 'passionate about', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'occasion', 'n.', '/əˈkeɪʒn/', '场合;时刻;时机', 'A skilled speaker can adjust a talk to cover almost any occasion.', '熟练的演讲者能调整演讲以适应几乎任何场合。', 'Achieving Effective Communication', 48, 0, 'senior', 'wordlist', 'elective4', 'U1', 'cover any occasion', NULL, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se4u1.01', '①定语从句:关系代词/关系副词(who/whom/whose/which/where/when)', 'A2', 12, '上外版选择性必修第四册 U1 — 看先行词(人/物/地点/时间/所属)和从句缺什么成分:人作主语 who、人前加介词 whom、表所属 whose、物作主/宾(不与 that 同现时)which、缺地点状语 where、缺时间状语 when。', 1, 'elective4', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se4u1.02', '②状语从句:让步/条件/结果/时间/原因连词', 'A2', 12, '上外版选择性必修第四册 U1 — 按逻辑关系选连词:让步 though/although/even though/no matter how;条件 unless/as long as/once;结果 so…that/such…that/so that(目的);时间 as soon as/while/until/before;原因 because/since。靠句意排除其他连词。', 2, 'elective4', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se4u1.03', '③名词性从句:主语/宾语/表语/同位语从句连接词(that/what/whether/why/how)', 'A2', 12, '上外版选择性必修第四册 U1 — 从句结构完整(不缺成分)用 that;从句缺主语或宾语用 what;一般疑问(常配 or not)用 whether;表原因用 why、表程度/方式用 how;''the fact/idea + that…'' 为同位语从句。', 3, 'elective4', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.01'), 'The lecturer ____ overcame his stage fright that night later became famous.', 'who', 'which', 'where', 'whose', 'A', '先行词 lecturer 指人、从句缺主语 → who;which 指物、where/whose 不能作主语。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.01'), 'Anyone ____ speaks in public for the first time may feel nervous.', 'whose', 'who', 'when', 'which', 'B', '先行词 anyone 指人、从句缺主语 → who。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.01'), 'The teacher ____ spelled words into Helen''s hand changed her whole life.', 'which', 'where', 'who', 'whose', 'C', '先行词 teacher 指人、缺主语 → who。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.01'), 'Speakers ____ truly engage the audience usually win warm applause.', 'where', 'when', 'which', 'who', 'D', '先行词 speakers 指人、缺主语 → who。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.01'), 'The friends ____ sat in the crowd pounded their clubs on the floor.', 'who', 'which', 'whose', 'where', 'A', '先行词 friends 指人、缺主语 → who。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.01'), 'The speaker ____ voice was trembling still managed to finish his talk.', 'who', 'whose', 'which', 'where', 'B', 'voice 属于 speaker、表所属 → whose。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.01'), 'Mark Twain, ____ humour delighted everyone, joked about his own age.', 'who', 'which', 'whose', 'whom', 'C', 'humour 属于 Twain、表所属 → whose。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.01'), 'Helen, ____ world had been silent and dark, longed to understand language.', 'who', 'which', 'where', 'whose', 'D', 'world 属于 Helen、表所属 → whose。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.01'), 'We admire writers ____ words can move millions of readers.', 'whose', 'who', 'which', 'when', 'A', 'words 属于 writers、表所属 → whose。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.01'), 'The governor''s wife, to ____ Twain glanced, led the whole hall in laughter.', 'who', 'whom', 'which', 'whose', 'B', '介词 to 后指人 → whom;who 不用于介词后,which 指物。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.01'), 'The audience for ____ he had prepared so hard sat in total silence.', 'which', 'who', 'whom', 'whose', 'C', '介词 for 后指人 → whom。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.01'), 'The teacher from ____ Helen learned everything was Miss Sullivan.', 'which', 'who', 'whose', 'whom', 'D', '介词 from 后指人 → whom。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.01'), 'The theatre ____ Twain gave his first lecture was dark and almost empty.', 'where', 'which', 'that', 'who', 'A', '先行词 theatre 表地点、从句不缺主宾(只缺地点状语)→ where。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.01'), 'Helen reached the well-house ____ the mystery of language was revealed to her.', 'which', 'where', 'that', 'when', 'B', '先行词 well-house 表地点、从句完整 → where。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.01'), 'A stage is a place ____ even brave people may suddenly freeze with fear.', 'which', 'when', 'where', 'that', 'C', '先行词 place 表地点、从句完整 → where。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.01'), 'I still recall the moment ____ my stage fright suddenly left me for good.', 'which', 'where', 'that', 'when', 'D', '先行词 moment 表时间、从句完整 → when。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.01'), 'There came a day ____ Helen finally understood that everything has a name.', 'when', 'where', 'which', 'that', 'A', '先行词 day 表时间、从句完整 → when。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.01'), 'Twain remembered the evening ____ he made his first bow as a lecturer.', 'that', 'when', 'which', 'where', 'B', '先行词 evening 表时间、从句完整 → when。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.01'), 'The manuscript ____ lay hidden under the flag was never actually used.', 'who', 'where', 'which', 'when', 'C', '先行词 manuscript 指物、从句缺主语且未与 that 同现 → which。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.01'), 'Modern technology, ____ keeps improving fast, now helps the blind communicate.', 'who', 'when', 'whose', 'which', 'D', '非限制性从句指物、缺主语 → which(此处不能用 that)。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.02'), '____ he was almost paralysed with fear, Mark Twain still walked onto the stage.', 'Though', 'Unless', 'So that', 'As soon as', 'A', '前后是让步关系(尽管害怕仍上台)→ Though。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.02'), 'Helen made steady progress ____ she could neither see nor hear.', 'because', 'although', 'unless', 'so that', 'B', '''既看不见又听不见''与''取得进步''是让步对比 → although。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.02'), 'You will gradually beat stage fright ____ you keep practising in front of others.', 'unless', 'although', 'as long as', 'because', 'C', '''只要坚持练习''是条件 → as long as;unless 表否定条件、意思相反。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.02'), 'You cannot really engage your listeners ____ you speak with genuine passion.', 'because', 'although', 'while', 'unless', 'D', '''除非满怀激情,否则吸引不了听众''→ unless(=if…not)。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.02'), '____ the audience feels involved, they will go on listening to you.', 'As long as', 'Unless', 'Although', 'Because', 'A', '''只要听众有参与感''是肯定条件 → As long as。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.02'), '____ you feel nervous inside, you should still look confident on stage.', 'Because', 'Even if', 'Unless', 'So that', 'B', '''即使内心紧张也要显得自信''是让步条件 → Even if。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.02'), 'He bound himself by a hard contract ____ he could not escape the lecture.', 'as if', 'even if', 'so that', 'now that', 'C', '''签合同''的目的是''无法逃避''→ so that(目的状语)。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.02'), 'Speakers move around the stage ____ their presentation feels lively and energetic.', 'as if', 'although', 'unless', 'so that', 'D', '走动的目的是让演讲显得有活力 → so that(目的)。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.02'), 'The whole hall was ____ quiet that you could have heard a pin drop.', 'so', 'such', 'very', 'too', 'A', '''so + 形容词 + that'' 引出结果状语从句 → so;such 接名词、very/too 不接 that 从句。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.02'), 'It was ____ a moving moment that the entire audience sat in silence.', 'so', 'such', 'very', 'too', 'B', '''such + a + 形容词 + 名词 + that'' 引出结果 → such。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.02'), '____ Twain glanced at the governor''s wife, the whole hall burst into laughter.', 'Unless', 'Although', 'As soon as', 'So that', 'C', '''一…就…''表时间紧接 → As soon as。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.02'), '____ she was drawing water from the well, Helen suddenly grasped the word.', 'Unless', 'Even if', 'So that', 'While', 'D', '''在打水的同时''表正在进行的背景时间 → While。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.02'), 'Helen kept confusing the two words ____ the truth finally dawned on her.', 'until', 'unless', 'although', 'because', 'A', '''一直混淆,直到真相显现''→ until(持续到某时间点)。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.02'), 'Several weeks passed ____ Helen realised that every object had its own name.', 'unless', 'before', 'although', 'so that', 'B', '''过了几周才…''→ before(…之前/才)。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.02'), 'The audience kept listening closely ____ the speaker sounded truly passionate.', 'although', 'unless', 'because', 'so that', 'C', '听众专注的原因是演讲者充满激情 → because(原因)。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.02'), '____ public speaking can be learned, there is really no need to fear it.', 'Unless', 'So that', 'As soon as', 'Since', 'D', '''既然演讲可以学会''是已知原因 → Since。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.02'), '____ hard the new word seemed, Helen simply refused to give up.', 'No matter how', 'As long as', 'Because', 'So that', 'A', '''无论这个词多难''是让步 → No matter how。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.02'), '____ Twain had spoken in public for years, he never forgot that first agony.', 'Because', 'Even though', 'Unless', 'So that', 'B', '''尽管已演讲多年''与''难忘初次煎熬''是让步 → Even though。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.02'), '____ you win the audience''s attention, holding on to it becomes much easier.', 'Unless', 'Although', 'Once', 'So that', 'C', '''一旦赢得注意''表条件/时间 → Once;Unless/Although 逻辑不通。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.02'), 'You should still sound natural ____ you are reading from a written script.', 'because', 'so that', 'as soon as', 'even if', 'D', '''即使在照稿念''也要自然 → even if(让步)。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.03'), '____ Helen learned that morning changed her whole world forever.', 'What', 'That', 'Whether', 'Why', 'A', '主语从句缺 learned 的宾语 → What;that 引导的主语从句须结构完整。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.03'), '____ communication sometimes breaks down is something we all experience.', 'What', 'That', 'Why', 'How', 'B', '从句 ''communication breaks down'' 结构完整、不缺成分 → That 引导主语从句。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.03'), 'Nobody in the hall could understand ____ the frightened speaker was mumbling.', 'that', 'whether', 'what', 'why', 'C', '宾语从句缺 mumbling 的宾语 → what。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.03'), 'Mark Twain admitted ____ stage fright felt like a terrible disease to him.', 'what', 'whether', 'how', 'that', 'D', '宾语从句结构完整、陈述事实 → that。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.03'), 'He honestly wasn''t sure ____ his little joke had really worked or not.', 'whether', 'that', 'what', 'why', 'A', '''…or not'' 表示是否、二选一 → whether。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.03'), 'A lack of confidence — that is ____ so many people are afraid of the stage.', 'because', 'why', 'what', 'how', 'B', '''that is why…'' 表语从句表原因 → why;because 不引导表语从句。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.03'), 'We were all amazed at ____ quickly Helen picked up so many new words.', 'that', 'what', 'how', 'why', 'C', '修饰 quickly 表程度 → how(how quickly)。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.03'), 'The fact ____ a deaf-blind girl could learn to read amazed the whole world.', 'what', 'which', 'why', 'that', 'D', '''the fact + 完整句子'' 为同位语从句 → that。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.03'), 'Real-time translation is exactly ____ travellers need most when they go abroad.', 'what', 'that', 'which', 'how', 'A', '表语从句缺 need 的宾语 → what。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.03'), 'Lucas keeps reminding us ____ a speech should aim to change people''s minds.', 'what', 'that', 'whether', 'why', 'B', '宾语从句结构完整 → that。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.03'), 'The team kept testing ____ the new app could read the labels aloud or not.', 'that', 'what', 'whether', 'how', 'C', '''…or not'' 表是否 → whether。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.03'), 'Helen''s early progress depended on ____ her teacher spelled into her palm.', 'that', 'which', 'why', 'what', 'D', '介词 on 后的宾语从句缺 spelled 的宾语 → what。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.03'), 'Listeners noticed ____ calmly the experienced speaker handled the tough question.', 'how', 'that', 'what', 'why', 'A', '修饰 calmly 表程度/方式 → how(how calmly)。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.03'), '____ the audience stays engaged or not depends largely on the speaker.', 'That', 'Whether', 'What', 'Why', 'B', '主语从句配 ''or not'' 表是否 → Whether(此处不可用 if)。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.03'), '____ matters most in a great speech is a genuine connection with people.', 'That', 'Whether', 'What', 'Why', 'C', '主语从句缺 matters 的主语 → What。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.03'), 'The nervous speaker promised ____ he would keep his talk short and lively.', 'what', 'whether', 'why', 'that', 'D', '宾语从句结构完整 → that。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.03'), 'It is really surprising ____ much our gestures add to the spoken words.', 'how', 'that', 'what', 'why', 'A', '修饰 much 表程度 → how(how much)。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.03'), 'Write down ____ you want to say clearly before you stand up to speak.', 'that', 'what', 'whether', 'how', 'B', '宾语从句缺 say 的宾语 → what。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.03'), 'The idea ____ technology can give a voice to the silent excites many scientists.', 'what', 'which', 'that', 'why', 'C', '''the idea + 完整句子'' 为同位语从句 → that。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U1' AND code='se4u1.03'), 'We often wonder ____ machines will ever truly understand us the way people do.', 'that', 'what', 'why', 'whether', 'D', 'wonder 后表''是否''、从句结构完整(understand 已带宾语 us)→ whether。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'The Night the Fear Left', 'When Mark Twain was still only a young reporter, he agreed to give his first public lecture. He was so afraid of failing that he signed a strict contract, which made it impossible for him to back out. On the evening of the talk, he reached the theatre nearly an hour early, his knees shaking so badly that he could hardly stand. To be safe, he arranged for several strong friends to sit among the listeners and bang their clubs on the floor whenever he said something meant to be funny. He also asked the governor''s wife to laugh loudly so that the rest of the hall would follow. In the middle of his speech he placed a touching story, and the audience fell completely silent. After about five minutes of pure misery, his fear suddenly disappeared and never came back. Years later he could still describe the agony of those opening moments in detail.', '记叙·吐温的初次演讲', 155, '[{"q":"Why did Mark Twain sign a strict contract before the lecture?","answer":"A","options":["To make sure he could not avoid giving the talk","To earn a larger payment for the evening","To force the theatre to lower its ticket prices","To win the support of the local governor"],"explanation":"他签合同是为了断了退路、逼自己上台,对应''无法退出''。"},{"q":"What was the purpose of the friends with clubs and the governor''s wife?","answer":"B","options":["To protect Twain from an angry crowd","To help spread laughter and applause through the hall","To time how long his speech lasted","To take notes on the audience''s reactions"],"explanation":"朋友敲棒、州长夫人大笑都是为了带动全场笑声与掌声。"},{"q":"How did Twain''s stage fright finally end?","answer":"A","options":["It vanished after a few painful minutes and stayed away","A friend stepped in to finish the talk","It slowly grew worse until he stopped","He left the stage and returned much calmer"],"explanation":"煎熬约五分钟后,恐惧突然消失且再没回来。"}]'::jsonb, '[{"word":"contract","cn":"合同;契约"},{"word":"agony","cn":"极度痛苦;煎熬"},{"word":"governor","cn":"州长;总督"}]'::jsonb, 2, 'elective4', 'U1', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'The Word at the Well', 'For weeks after her teacher arrived, Helen Keller copied finger signs without grasping what they meant. She could form the letters for many objects, yet she had no idea that these shapes stood for real things. One morning she kept mixing up the signs for two different objects, grew angry, and threw a doll to the floor. Her teacher quietly swept the broken pieces aside and led her outside into the warm sunshine. They walked down to the well-house, where someone was drawing water. Her teacher placed one of Helen''s hands under the flowing tap and spelled the word for water into the other, first slowly and then quickly. All at once a misty feeling of something long forgotten rushed back to her. In that single moment Helen understood that the cool stream pouring over her hand had a name. She left the well eager to learn, certain now that everything in the world could be named.', '记叙·海伦·凯勒理解语言', 157, '[{"q":"What was Helen''s main problem before the moment at the well?","answer":"B","options":["She could not move her fingers at all","She copied signs without understanding their meaning","She refused to let her teacher touch her hands","She had already learned to read printed books"],"explanation":"她只是机械模仿手势,并不明白其含义。"},{"q":"What finally happened to Helen beside the running water?","answer":"C","options":["She learned to speak her first full sentence","She remembered the doll she had broken earlier","She suddenly grasped that the water had its own name","She decided she no longer wanted to study"],"explanation":"水流过手时,她突然懂得这事物是有名字的。"},{"q":"How did Helen feel as she left the well-house?","answer":"D","options":["Tired and ready to rest","Confused about what had happened","Angry at her strict teacher","Hungry to learn the names of everything"],"explanation":"她离开时''渴望学习'',想知道一切的名字。"}]'::jsonb, '[{"word":"sign","cn":"手势;符号"},{"word":"well-house","cn":"井房"},{"word":"tap","cn":"水龙头"}]'::jsonb, 2, 'elective4', 'U1', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Reading with the Fingers', 'Braille is a clever system that lets people who cannot see read and write by touch. Each letter is formed from a small pattern of raised dots, and the fingers move across the page to feel them one by one. Because the same dot patterns can be borrowed by many languages, Braille is now used around the world for English, Chinese, Arabic and dozens of others. The system is named after Louis Braille, a Frenchman who lost his eyesight in an accident when he was a small child. As a student he was unhappy with the clumsy reading methods of his day, so he designed a simpler code that ordinary fingers could follow quickly. Today his invention does far more than print books. It appears on lift buttons, medicine boxes and signs in public places, giving blind people greater freedom to live and communicate on their own. A single good idea changed millions of lives.', '说明·盲文及其发明者', 155, '[{"q":"How do readers use Braille?","answer":"A","options":["By feeling patterns of raised dots with their fingers","By listening to spoken letters","By looking at large coloured pictures","By pressing buttons that speak each word"],"explanation":"盲文靠手指触摸凸点来阅读。"},{"q":"Why is Braille described as useful for many languages?","answer":"B","options":["It can only be written in French","Its dot patterns can be shared by different languages","It uses a different alphabet for every country","It replaces all printed letters with pictures"],"explanation":"同样的凸点组合可被多种语言借用。"},{"q":"What does the passage suggest about Braille''s value today?","answer":"C","options":["It is mainly used for printing storybooks","It has been replaced by newer machines","It helps blind people manage daily life more independently","It is too difficult for most people to learn"],"explanation":"盲文出现在电梯、药盒、标识上,让盲人更独立地生活交流。"}]'::jsonb, '[{"word":"raised dots","cn":"凸点"},{"word":"code","cn":"代码;符号系统"},{"word":"invention","cn":"发明"}]'::jsonb, 2, 'elective4', 'U1', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Lending a Voice to the Silent', 'Some people cannot speak with their own voice, yet modern technology is finding new ways to give them one. A famous scientist who could move only a single muscle in his cheek once relied on a computer to talk for him. A small sensor noticed each tiny movement, and special software studied his old writings to guess which letter he was likely to choose next. Step by step, the machine turned his slow signals into full sentences and then into clear speech. Newer tools try to read movements even faster, while a few research teams are testing systems that could one day work directly from brain signals. For travellers, simple phone apps now translate between languages almost instantly, and other apps describe the world aloud for users who cannot see. None of these tools is perfect, but together they are slowly removing barriers that once kept many people silent. The goal is simple: to let everyone join the conversation.', '说明·辅助科技与交流', 159, '[{"q":"How did the scientist''s computer help him speak?","answer":"D","options":["It read his thoughts directly from his brain","It recorded his voice and played it back","It translated his writing into other languages","It turned tiny cheek movements into words and speech"],"explanation":"传感器捕捉脸颊微动,软件预测字母,再转为语音。"},{"q":"What are some newer technologies trying to do?","answer":"A","options":["Work from brain signals and read movements faster","Make all old apps stop working","Teach people to write with their hands again","Replace human conversation completely"],"explanation":"新工具尝试更快读取动作,甚至直接用脑信号。"},{"q":"What is the writer''s overall attitude towards these tools?","answer":"B","options":["They are useless and should be dropped","They are imperfect but helpfully removing barriers","They are dangerous to ordinary speakers","They are already perfect and need no change"],"explanation":"作者认为工具虽不完美,却在逐步消除交流障碍。"}]'::jsonb, '[{"word":"sensor","cn":"传感器"},{"word":"software","cn":"软件"},{"word":"signal","cn":"信号"}]'::jsonb, 2, 'elective4', 'U1', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'What Gets in the Way', 'Even when two people share a language, communication can still go wrong. Experts often sort the problems into four groups. The first is psychological: fear or shyness, such as stage fright, can stop a message before it leaves our mouths. The second is physical: poor hearing or weak sight may block words and signs, though hearing aids and glasses often help. The third is the language barrier, which appears when speakers do not share the same tongue; here a reliable translator or a few clear gestures can bridge the gap. The fourth is cultural: a joke or a habit that feels polite in one country may seem strange or even rude in another. The most useful cure for this last barrier is not a clever device but an honest respect for differences. Knowing which barrier you face is the first step, because each kind calls for its own simple strategy rather than a single fix.', '说明·四类交流障碍', 155, '[{"q":"According to the passage, what is a psychological barrier?","answer":"C","options":["Not sharing the same language","Weak hearing or poor eyesight","Fear or shyness that holds a message back","A custom that seems rude abroad"],"explanation":"心理障碍指怯场等恐惧或害羞,使信息说不出口。"},{"q":"What does the writer suggest works best against the cultural barrier?","answer":"D","options":["A powerful new device","Speaking much more loudly","Avoiding foreigners altogether","A sincere respect for differences"],"explanation":"对待文化障碍最有效的是真诚尊重差异,而非设备。"},{"q":"What is the main point of the final sentence?","answer":"A","options":["Different barriers each need their own strategy","One single method can fix every barrier","Barriers can never really be overcome","Only language barriers truly matter"],"explanation":"每类障碍都需各自的对策,没有万能办法。"}]'::jsonb, '[{"word":"shyness","cn":"害羞"},{"word":"hearing aid","cn":"助听器"},{"word":"strategy","cn":"策略"}]'::jsonb, 2, 'elective4', 'U1', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Holding the Room', 'Keeping an audience interested is one of the hardest parts of public speaking, especially when you are nervous. A few simple habits make a real difference. First, speak with passion, since listeners can tell at once whether you care about your subject; caring about it also helps calm your own fear. Second, use the stage. Moving as you change topics, or stepping closer as you ask a question, gives your talk energy, while standing frozen like a board builds a wall between you and the room. Third, let a little of your personality show. A short personal story or a touch of humour, used where it fits, makes people warm to you. Finally, offer something of real value instead of sounding like a salesperson. Audiences quickly sense pressure and grow resistant, but they stay open when they feel you are giving rather than selling. Practise these habits and even a shy speaker can hold the room.', '说明·如何吸引听众', 156, '[{"q":"Why does the writer recommend speaking with passion?","answer":"B","options":["It makes a speech much shorter","Listeners notice it and the speaker''s fear eases","It hides any mistakes in the notes","It forces the audience to take notes"],"explanation":"充满激情既能被听众察觉,也能缓解演讲者自身的恐惧。"},{"q":"What does standing frozen on stage do, according to the text?","answer":"C","options":["It gives the talk extra energy","It helps the speaker remember more","It puts a wall between speaker and audience","It makes the speech sound more polite"],"explanation":"一动不动会在演讲者与听众之间筑起一道墙。"},{"q":"Why might an audience become resistant?","answer":"D","options":["When the speaker shares a personal story","When the speaker moves around the stage","When the speech offers something valuable","When the talk feels like a sales pitch under pressure"],"explanation":"当演讲像在施压推销时,听众会产生抵触。"}]'::jsonb, '[{"word":"passion","cn":"激情;热情"},{"word":"personality","cn":"个性;性格"},{"word":"value","cn":"价值"}]'::jsonb, 2, 'elective4', 'U1', 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U1', 'Getting Ready for the Talk', 'The best speakers rarely sound nervous, but that calm is not an accident. Most of them (1) hours of quiet practice before they ever face a crowd. Lan was asked to (2) a short speech at her school''s science week. At first the very (3) of standing in front of two hundred classmates made her hands shake. Her teacher gave her a piece of (4): read the words aloud again and again until they felt natural. So every evening Lan stood in front of a mirror and (5) her whole talk. She also recorded her voice so that she could (6) her own pace and tone. Slowly the strange sentences began to feel (7) hers. By the day of the event, she no longer needed to (8) the printed page. She walked onto the stage, took a deep breath, and (9) at the audience with a smile. The (10) of all that practice was a calm, confident talk.', 158, 2, '[{"q":"1","answer":"A","options":["put in","give up","call off","throw away"],"explanation":"''投入''数小时练习 → put in;其余意思不通。"},{"q":"2","answer":"B","options":["delay","deliver","delete","design"],"explanation":"deliver a speech 发表演讲。"},{"q":"3","answer":"C","options":["habit","reward","thought","promise"],"explanation":"''一想到站在台前''→ the thought of。"},{"q":"4","answer":"D","options":["order","warning","praise","advice"],"explanation":"老师给的是建议 → advice。"},{"q":"5","answer":"A","options":["practised","ignored","lost","forgot"],"explanation":"对着镜子练习整篇 → practised。"},{"q":"6","answer":"B","options":["waste","check","hide","spend"],"explanation":"录音是为了检查语速语调 → check。"},{"q":"7","answer":"C","options":["hardly","rarely","truly","never"],"explanation":"句子开始''真正''像她自己的 → truly。"},{"q":"8","answer":"D","options":["tear up","throw at","laugh at","read from"],"explanation":"不再需要照着稿子念 → read from。"},{"q":"9","answer":"A","options":["looked","shouted","ran","pointed"],"explanation":"微笑着望向观众 → looked。"},{"q":"10","answer":"B","options":["problem","result","danger","excuse"],"explanation":"练习的结果是镇定自信 → result。"}]'::jsonb, 1, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U1', 'My First Presentation', 'I will never forget my first class presentation. When my teacher read out my name, my heart began to (1) so fast that I could hear it. I walked to the front on (2) legs and stared at a sea of faces. For a moment my mind went completely (3), and I forgot every word I had prepared. Then I remembered my friend''s tip: find one (4) face and speak to it. So I looked at my best friend, who gave me an encouraging (5). Slowly my voice grew (6), and the shaking in my hands began to fade. I started to use my hands to (7) what I meant, just as we had been taught. To my surprise, the class actually (8) to what I was saying. When I finished, they gave me a warm round of (9). That day I learned that fear is normal, but it does not have to (10) us.', 155, 2, '[{"q":"1","answer":"C","options":["sleep","melt","beat","freeze"],"explanation":"心脏''跳''得很快 → beat。"},{"q":"2","answer":"D","options":["running","sleeping","waving","shaking"],"explanation":"双腿发抖 → shaking。"},{"q":"3","answer":"A","options":["blank","bright","wide","loud"],"explanation":"脑子一片空白 → went blank。"},{"q":"4","answer":"B","options":["angry","friendly","empty","broken"],"explanation":"找一张''友善的''脸 → friendly。"},{"q":"5","answer":"C","options":["shout","push","smile","rule"],"explanation":"朋友给了鼓励的微笑 → smile。"},{"q":"6","answer":"D","options":["quieter","colder","darker","steadier"],"explanation":"声音逐渐''稳''了下来 → steadier。"},{"q":"7","answer":"A","options":["show","hide","buy","spell"],"explanation":"用手势''展示''含义 → show。"},{"q":"8","answer":"B","options":["objected","listened","belonged","pointed"],"explanation":"全班在''倾听'' → listened (to)。"},{"q":"9","answer":"C","options":["silence","questions","applause","homework"],"explanation":"热烈的''掌声'' → applause。"},{"q":"10","answer":"D","options":["help","teach","thank","control"],"explanation":"恐惧不必''控制''我们 → control。"}]'::jsonb, 2, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U1', 'Sending Messages Through Time', 'Long before phones existed, people still found clever ways to send (1) over long distances. On open hills, soldiers lit fires and used rising (2) to warn of danger far away. Sailors at sea raised coloured flags, while travellers trained (3) to carry tiny notes home. Later, a code of short and long signals let operators tap out words along a wire, which made news (4) much faster than any horse. The telephone then allowed two people to (5) directly, even when they were miles (6). In our own time, the Internet has changed everything once (7). A message can now cross the planet in less than a (8). Yet the basic aim has never (9): to share an idea with someone who is not standing beside us. Each new tool simply makes that ancient wish a little (10) to reach.', 141, 2, '[{"q":"1","answer":"A","options":["messages","buildings","animals","mountains"],"explanation":"远距离传''信息'' → messages。"},{"q":"2","answer":"B","options":["water","smoke","sand","grass"],"explanation":"升起的''烟''(烽烟报警)→ smoke。"},{"q":"3","answer":"C","options":["horses","fish","pigeons","lions"],"explanation":"训练''鸽子''送信 → pigeons。"},{"q":"4","answer":"D","options":["stop","sleep","fall","travel"],"explanation":"电报让消息''传播''更快 → travel。"},{"q":"5","answer":"A","options":["talk","fight","walk","wait"],"explanation":"电话让两人直接''交谈'' → talk。"},{"q":"6","answer":"B","options":["ahead","apart","along","aside"],"explanation":"相隔很远 → miles apart。"},{"q":"7","answer":"C","options":["never","hardly","again","rarely"],"explanation":"互联网''再次''改变一切 → again。"},{"q":"8","answer":"D","options":["year","mile","page","second"],"explanation":"不到一''秒''传遍全球 → second。"},{"q":"9","answer":"A","options":["changed","helped","moved","opened"],"explanation":"基本目的从未''改变'' → changed。"},{"q":"10","answer":"B","options":["harder","easier","slower","darker"],"explanation":"让愿望更''容易''实现 → easier。"}]'::jsonb, 3, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U1', 'A Seat at the Front', 'Tom was born with very weak hearing, and for years he sat (1) at the back of the classroom, missing half of every lesson. He often felt (2) out, as if a wall stood between him and his classmates. Last term, his school decided to (3) some new technology. A small microphone now sends the teacher''s voice straight to a device in Tom''s ear, so the words arrive (4) and clear. A screen at the front also shows the speech as written (5), so he can read whatever he might miss. The change has been (6). For the first time, Tom can follow a fast discussion and even (7) his own questions without fear. His classmates say he has become far more (8) in group work. Tom himself says the hardest barrier was never his ears but the (9) of being left out. With the right help, that barrier has finally come (10).', 153, 2, '[{"q":"1","answer":"C","options":["loudly","proudly","quietly","happily"],"explanation":"安静地坐在后排 → quietly。"},{"q":"2","answer":"D","options":["given","taken","put","left"],"explanation":"感到被''冷落'' → left out。"},{"q":"3","answer":"A","options":["try","sell","break","hide"],"explanation":"学校决定''尝试''新技术 → try。"},{"q":"4","answer":"B","options":["dark","loud","late","cold"],"explanation":"声音传来既''响亮''又清晰 → loud。"},{"q":"5","answer":"C","options":["songs","colours","words","numbers"],"explanation":"屏幕显示成文字 → words。"},{"q":"6","answer":"D","options":["tiny","false","rude","huge"],"explanation":"变化是''巨大的'' → huge。"},{"q":"7","answer":"A","options":["ask","miss","lose","drop"],"explanation":"毫无畏惧地''提出''问题 → ask。"},{"q":"8","answer":"B","options":["silent","active","absent","tired"],"explanation":"在小组中更''积极'' → active。"},{"q":"9","answer":"C","options":["joy","habit","fear","rule"],"explanation":"最难的障碍是被排斥的''恐惧'' → fear。"},{"q":"10","answer":"D","options":["back","true","alive","down"],"explanation":"障碍终于''倒下'' → come down。"}]'::jsonb, 4, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U1', 'Talking Through a Screen', 'Video calls have made it easy to meet people far away, yet they bring their own small (1). On a screen, others cannot fully see your body, so your face and voice must do (2) of the work. Before an important call, it is wise to (3) your camera and microphone so that nothing fails at the wrong moment. Sit where the light falls on your face rather than (4) you, or you will appear as a dark shape. Look into the camera, not at the screen, so that the other person feels you are making eye (5) with them. Speak a little more (6) than usual, and pause now and then to let your words (7) in. If the connection is poor, do not shout; instead, repeat the key (8) calmly. Above all, give the speaker your full (9), since people can always tell when you are checking another window. Good manners (10) just as much online as they do face to face.', 164, 2, '[{"q":"1","answer":"A","options":["challenges","rewards","holidays","machines"],"explanation":"带来自己的小''挑战'' → challenges。"},{"q":"2","answer":"B","options":["none","most","little","least"],"explanation":"脸和声音得承担''大部分''工作 → most。"},{"q":"3","answer":"C","options":["break","sell","test","paint"],"explanation":"事先''测试''摄像头麦克风 → test。"},{"q":"4","answer":"D","options":["beside","below","between","behind"],"explanation":"光应照在脸上而非身后 → behind。"},{"q":"5","answer":"A","options":["contact","level","shadow","corner"],"explanation":"眼神交流 → eye contact。"},{"q":"6","answer":"B","options":["rudely","slowly","wildly","sadly"],"explanation":"比平时说得更''慢''些 → slowly。"},{"q":"7","answer":"C","options":["fall","jump","sink","melt"],"explanation":"让话语''沉入''(被吸收)→ sink in。"},{"q":"8","answer":"D","options":["doors","prices","seats","points"],"explanation":"平静地重复关键''要点'' → points。"},{"q":"9","answer":"A","options":["attention","money","homework","distance"],"explanation":"给予全部''注意力'' → attention。"},{"q":"10","answer":"B","options":["cost","matter","stop","fail"],"explanation":"礼貌同样''重要'' → matter。"}]'::jsonb, 5, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U1', 'Friends Behind the Screen', 'Our class recently ran a small (1) to find out how social media affects the way we talk to each other. We asked forty students about their favourite (2) of keeping in touch. The (3) surprised us. Although almost everyone used chat apps every day, most still said they (4) face-to-face talks for anything important. Many admitted that they often check their phones while (5) time with family, a habit they were not (6) of. Several students felt that endless messages had actually made them feel more (7), not less, because a screen hides real feelings. Others, however, argued that apps help shy people (8) friendships they would never start in person. In the end we (9) that technology is neither all good nor all bad; it simply depends on how we use it. The wisest plan, we decided, is to let our phones (10) real conversation, never replace it.', 150, 2, '[{"q":"1","answer":"C","options":["concert","lesson","survey","journey"],"explanation":"做了一个小''调查'' → survey。"},{"q":"2","answer":"D","options":["day","rule","price","way"],"explanation":"最喜欢的联系''方式'' → way。"},{"q":"3","answer":"A","options":["result","weather","ticket","machine"],"explanation":"调查的''结果''让人意外 → result。"},{"q":"4","answer":"B","options":["refused","preferred","feared","missed"],"explanation":"重要事情更''偏爱''面谈 → preferred。"},{"q":"5","answer":"C","options":["wasting","saving","spending","buying"],"explanation":"与家人''共度''时光 → spending time。"},{"q":"6","answer":"D","options":["afraid","fond","tired","aware"],"explanation":"并未''意识到''这一习惯 → aware of。"},{"q":"7","answer":"A","options":["alone","proud","polite","awake"],"explanation":"反而感到更''孤独'' → alone。"},{"q":"8","answer":"B","options":["break","build","lose","sell"],"explanation":"帮助腼腆者''建立''友谊 → build。"},{"q":"9","answer":"C","options":["refused","doubted","agreed","complained"],"explanation":"最后我们''一致认为'' → agreed。"},{"q":"10","answer":"D","options":["replace","stop","delay","support"],"explanation":"让手机''辅助''而非取代真实交流 → support。"}]'::jsonb, 6, 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'Calming the Nerves', '上外版选择性必修第四册 U1 · dialogue 两名学生赛前准备', 3, 'Mia: Leo, the speech contest is on Friday and I''m already terrified. My hands shake whenever I imagine the stage.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'Workshop Announcement', '上外版选择性必修第四册 U1 · monologue 校园广播通知', 2, 'Good morning, everyone. This is a quick reminder from the students'' union. Next Wednesday afternoon, we are holding a free workshop called ''Speak with Confidence'' in the school library. The trainer is a former television presenter who has coached many nervous beginners. She will show you how to control your breathing, how to use simple gestures, and how to keep an audience interested even when you feel shy. Places are limited to thirty students, so please sign up by Monday at the union office. Remember to bring a short two-minute talk on any topic you like, because everyone will get the chance to practise in a friendly group. Don''t worry if you have never spoken in public before — that is exactly what this workshop is for. We hope to see many of you there.', '早上好。学生会通知:下周三下午将在学校图书馆举办免费工作坊“自信演讲”。培训师是一位曾任电视主持人、辅导过许多紧张新手的老师。她将教大家如何控制呼吸、如何使用简单手势,以及在害羞时如何吸引听众。名额限三十人,请周一前到学生会办公室报名。请准备一个两分钟的任意话题短演讲,因为每人都将在友好的小组中练习。从未公开演讲过也别担心,这正是工作坊的意义所在。期待大家参加。', 'uk_male', '[{"q":"Where will the workshop be held?","type":"choice","answer":"D","options":["In the sports hall","In the union office","On the playground","In the school library"]},{"q":"Who is the trainer?","type":"choice","answer":"A","options":["A former television presenter","A famous singer","The school headmaster","A university professor"]},{"q":"What is one thing the trainer will teach?","type":"choice","answer":"B","options":["How to write a novel","How to control your breathing","How to design a poster","How to record music"]},{"q":"How can students get a place?","type":"choice","answer":"C","options":["Pay a fee at the door","Email the trainer directly","Sign up at the union office by Monday","Just turn up on Wednesday"]},{"q":"What should students bring to the workshop?","type":"choice","answer":"D","options":["A musical instrument","A laptop computer","A printed newspaper","A short two-minute talk"]}]'::jsonb, '[]'::jsonb, 'short', 'elective4', 'U1', 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'An App for Shoppers', '上外版选择性必修第四册 U1 · dialogue 小组讨论科技方案', 3, 'Sara: For our science-week project, let''s solve a real communication problem. What about helping blind people do their shopping?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'When Words Don''t Reach', '上外版选择性必修第四册 U1 · monologue 播客谈生理障碍对策', 2, 'Welcome back to the podcast. Today I want to focus on one type of communication barrier: the physical kind. This happens when a person''s hearing or sight makes it hard for a message to get through. The good news is that simple strategies can help a great deal. If someone has weak hearing, face them directly, speak clearly, and don''t cover your mouth. A hearing aid or a quiet room can make a huge difference. If someone has poor sight, describe what is around you instead of just pointing, and read out any important signs. And whatever the barrier, check often that the other person has understood, rather than rushing on. Remember, the goal is not to speak louder, but to make sure your meaning truly arrives. A little patience turns a barrier into a small step.', '欢迎回到播客。今天我想聚焦一类交流障碍——生理障碍,即一个人的听力或视力使信息难以传达。好消息是,简单的策略能帮上大忙。若对方听力弱,要正对着他、说清楚、别捂嘴;助听器或安静的环境会大不相同。若对方视力差,要描述周围的事物而非只是用手指,并读出重要的标识。无论何种障碍,都要经常确认对方是否听懂,而不是一味往下赶。记住,目标不是说得更大声,而是确保你的意思真正传达到。一点耐心就能把障碍变成一个小小的台阶。', 'uk_female', '[{"q":"Which barrier does the podcast focus on today?","type":"choice","answer":"B","options":["The cultural barrier","The physical barrier","The language barrier","The money barrier"]},{"q":"What should you do when talking to someone with weak hearing?","type":"choice","answer":"C","options":["Whisper from behind them","Write everything in another language","Face them and speak clearly without covering your mouth","Turn off all the lights"]},{"q":"What helps when someone has poor sight?","type":"choice","answer":"D","options":["Pointing silently at things","Speaking much faster","Showing them colourful pictures","Describing what is around them instead of pointing"]},{"q":"What does the speaker say you should do often?","type":"choice","answer":"A","options":["Check that the other person has understood","Repeat every word three times","Change the subject quickly","Speak in a foreign accent"]},{"q":"What is the speaker''s main message?","type":"choice","answer":"B","options":["Loud voices solve every problem","The aim is to make your meaning arrive, not just to be louder","Barriers can never be reduced","Patience makes communication harder"]}]'::jsonb, '[]'::jsonb, 'short', 'elective4', 'U1', 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'Feedback After the Talk', '上外版选择性必修第四册 U1 · dialogue 师生演讲反馈', 3, 'Mr Reed: Well done, Anna. That was a brave first speech. May I share a few thoughts to help you improve?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'Writing a Good Summary', '上外版选择性必修第四册 U1 · monologue 学习策略独白', 2, 'If a friend misses a talk, a clear summary is a kind gift. But writing one well takes a little skill. First, listen or read for the shape of the whole piece, not just single facts. Many talks follow a general-to-specific pattern: the speaker makes one big point, then supports it with several details. Your job is to catch that main point first and put it in your own words. After that, pick only the two or three details that really matter, and leave out the small examples. Keep your summary short — often under sixty words — and never copy long phrases straight from the speaker. Finally, read your summary once more to check that it makes sense on its own, even to someone who was not there. A good summary is not shorter writing; it is clearer thinking.', '如果朋友错过了一场演讲,一份清晰的摘要就是一份善意的礼物,但写好它需要一点技巧。首先,要把握整篇的结构,而非只抓零碎事实。许多演讲遵循“由总到分”的模式:讲者先提出一个大观点,再用若干细节支撑。你的任务是先抓住主旨并用自己的话表达。之后,只挑出两三个真正重要的细节,略去小例子。摘要要短——常少于六十词——且绝不照抄讲者的长句。最后,再读一遍,确认它独立成篇、即使没在场的人也能看懂。好的摘要不是更短的文字,而是更清晰的思考。', 'uk_female', '[{"q":"What should you listen for first when writing a summary?","type":"choice","answer":"D","options":["Every single small fact","The speaker''s clothes","The length of the room","The shape of the whole piece"]},{"q":"What pattern do many talks follow, according to the speaker?","type":"choice","answer":"A","options":["A general point supported by details","A list of unrelated jokes","A song followed by a dance","A series of questions only"]},{"q":"How should you express the main point?","type":"choice","answer":"B","options":["By copying long phrases exactly","In your own words","In another language","Only with pictures"]},{"q":"How long should the summary usually be?","type":"choice","answer":"C","options":["At least five pages","Exactly one hundred words","Often under sixty words","As long as the original talk"]},{"q":"What is the final check the speaker recommends?","type":"choice","answer":"D","options":["That it rhymes nicely","That it is longer than the talk","That it uses difficult words","That the summary makes sense on its own"]}]'::jsonb, '[]'::jsonb, 'short', 'elective4', 'U1', 'sufe');
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (12, 'Write a Summary of a General-Specific Speech(为一篇“总—分”演讲写摘要)', 'A Summary of "How to Keep Your Audience Engaged"', '一位演讲者在你校做了题为《如何在演讲时让听众保持专注》的报告。你的朋友很感兴趣却未能到场,请你用英语写一篇不超过60词的摘要分享给他/她。要求:① 用一句话概括演讲的总观点;② 用自己的话提炼出三到四条具体建议;③ 不照抄原文长句,代词指代清楚、句句围绕中心。', 'A speaker gave a talk at your school called "How to Keep Your Audience Engaged While Delivering a Speech." A friend was interested but could not attend. Write a summary in no more than 60 words including: 1) one sentence stating the speaker''s general point; 2) three or four key pieces of advice in your own words; 3) no long copying from the original, with clear pronoun reference.', '["总述句概括(The speaker explained how to keep listeners engaged …)","提炼要点1-2(speak with passion; move on stage)","提炼要点3-4(show some personality; offer real value, not a sales pitch)","用自己的话改写、不超60词、句句围绕中心"]'::jsonb, 70, 100, 'In her talk, the speaker explained how to keep an audience engaged during a speech. She advised speakers to talk with real passion, to move around the stage to add energy, and to let a little personality show through stories or humour. Above all, she said, offer the listeners something truly valuable instead of sounding like a salesperson.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["The speaker explained how to keep an audience engaged during a speech.","She advised speakers to talk with real passion and to move around the stage.","Letting a little personality show makes listeners warm to you.","Offer the audience something truly valuable instead of sounding like a salesperson."]'::jsonb, '[{"wrong":"The speaker explained how to keep engaged the audience.","correct":"The speaker explained how to keep the audience engaged.","note":"keep + 宾语 + 形容词,宾语放在 keep 之后。"},{"wrong":"She advised speakers talk with passion.","correct":"She advised speakers to talk with passion.","note":"advise sb to do sth,不定式带 to。"},{"wrong":"Offer something valuable instead of to sound like a salesperson.","correct":"Offer something valuable instead of sounding like a salesperson.","note":"instead of 后接动名词 -ing。"}]'::jsonb, '【总—分演讲摘要结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (12, 'elective4', 'U1', '{"title":"复杂句综合·定语/状语/名词性从句速查","intro":"复杂句 = 主句 + 一个或多个从句,从句由从属连接词引导。判断三步:① 这是哪类从句(看它在主句里充当什么)② 从句缺不缺成分 ③ 表达什么逻辑/语气,据此选连接词。","table":{"headers":["从句类型","判断要点 / 常用连接词 / 例句"],"rows":[["定语从句","修饰名词;人作主语 who、人加介词 whom、所属 whose、物 which、缺地点状语 where、缺时间状语 when:the teacher who helped me"],["状语从句","作状语表逻辑;让步 though/even if、条件 unless/as long as/once、结果 so…that/such…that、目的 so that、时间 as soon as/while/until、原因 because/since:Once you start, it gets easier."],["名词性从句","作主/宾/表/同位语;完整句用 that、缺主宾用 what、是否用 whether(配 or not)、原因 why、程度 how:What matters is practice."],["关键对比","that vs what 看从句缺不缺成分;whether vs that 看是否表''是非'';that is why 表原因结论"]]},"specialRules":[{"rule":"定从:从句缺主语/宾语用关系代词,只缺状语才用关系副词","mark":"the day when (缺时间状语) vs the day that changed… (缺主语)"},{"rule":"名从:从句结构完整用 that,缺主语或宾语用 what","mark":"That he came surprised us. / What he said surprised us."},{"rule":"结果状语:so + 形/副 + that;such + (a) + 形 + 名 + that","mark":"so quiet that… / such a moment that…"},{"rule":"条件/让步:unless = if…not;even if 即使;no matter how 无论多么","mark":"You can''t win them unless you sound real."}],"why":["复杂句的难点不在认识单个连接词,而在''先分清从句类型、再看从句缺什么成分'':同一个 that,在定语从句里是关系代词(可省略、可换 which),在名词性从句里是连词(不充当成分、常不可省);what 永远要在从句里充当主语或宾语。"],"gaokaoPoints":["语法填空/写作高频:定从关系词(who/which/whose/where/when/介词+which)、名从连接词(that/what/whether/why/how)、状语从句连词据逻辑选择。","易错点:that vs what(看缺不缺成分)、whether vs if(主语从句、介词后、+or not 只用 whether)、so…that vs such…that。"],"examVsReal":[{"exam":"I don''t know whether he will come or not.（考试/正式）","real":"I don''t know if he''ll come.","note":"口语里 if 更常见;但主语从句、介词后、+or not 仍只能用 whether"},{"exam":"The reason why he left is unclear.（考试)","real":"The reason he left is unclear.","note":"口语常省略 why/that;书面考试保留更稳妥"},{"exam":"It was so cold that we stayed in.（考试强调 so…that 结构)","real":"It was really cold, so we stayed in.","note":"真实英语常拆成两句用 so 连接,更口语化"}]}'::jsonb, 'sufe');
